// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D1: DELETE masivo sin WHERE (> 100 filas por ejecución). Una alerta por consulta detectada.
const tablaDe = (q, verbo) => {
  const re = verbo === 'DELETE' ? /^\s*delete\s+from\s+(?:only\s+)?([\w."]+)/i : /^\s*update\s+(?:only\s+)?([\w."]+)/i;
  return ((String(q).match(re) || [])[1] || 'desconocida').replace(/"/g, '');
};
const filas = $input.all().map(i => i.json).filter(r => r.queryid);
return filas.map(r => ({ json: {
  codigo: 'D1',
  severidad: 'CRÍTICA',
  tipo: 'DELETE masivo sin WHERE detectado',
  tabla: tablaDe(r.query, 'DELETE'),
  detalle: `Filas borradas: ${r.filas_por_ejecucion} por ejecución (umbral: 100). Ejecuciones: ${r.calls}. queryid ${r.queryid}`,
  query: r.query,
  usuario: r.usuario,
  accion: 'Verificar si el borrado estaba autorizado. Recuperar filas desde auditoria_datos (valor_antes) o desde el último respaldo.'
}}));
